<script setup lang="ts">
import { ticketTypeLabel } from '~~/shared/template'
const props = defineProps<{ ev: any }>(); const emit = defineEmits<{ refresh: [] }>(); const toast = useToast()
const kinds: [string, string][] = [['free', 'Gratuit'], ['standard', 'Standard'], ['vip', 'VIP'], ['backstage', 'Backstage'], ['early_bird', 'Early bird'], ['group', 'Groupe'], ['custom', 'Personnalisée']]
const n = reactive({ name: '', kind: 'standard', customType: '', price: 5000, quota: 100, maxPerOrder: undefined as number | undefined, vip: false, templateId: '' }); const busy = ref(false)
const { data: templates, error: templatesError } = await useAsyncData(`category-tpls-${props.ev.id}`, () => api<any[]>('/api/templates', { query: { orgId: props.ev.organizationId } }), { server: false })
const eventTemplateLabel = computed(() => props.ev.templateId
  ? templates.value?.find((template) => template.id === props.ev.templateId)?.name ?? 'Modèle événementiel'
  : 'Modèle TYPS par défaut')
const dt = (v?: string) => (v ? new Date(v).toISOString() : null)
async function add() { busy.value = true; try { await api(`/api/manage/events/${props.ev.id}/categories`, { method: 'POST', body: { ...n, customType: n.kind === 'custom' ? n.customType.trim() : null, templateId: n.templateId || null, vip: n.vip || n.kind === 'vip' || n.kind === 'backstage', maxPerOrder: n.maxPerOrder || undefined } }); toast.ok('Catégorie ajoutée'); n.name = ''; n.customType = ''; n.templateId = ''; emit('refresh') } catch (e) { toast.err(errMsg(e)) } finally { busy.value = false } }
const edit = reactive<Record<string, { price: number; quota: number; saleStart: string; saleEnd: string; customType: string; templateId: string }>>({})
const loc = (d: string | null) => (d ? new Date(new Date(d).getTime() - new Date(d).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : '')
const start = (c: any) => { edit[c.id] = { price: c.price, quota: c.quota, saleStart: loc(c.saleStart), saleEnd: loc(c.saleEnd), customType: c.customType ?? '', templateId: c.templateId ?? '' } }
const templateName = (id: string | null) => id
  ? templates.value?.find((template) => template.id === id)?.name ?? 'Modèle personnalisé'
  : eventTemplateLabel.value
async function saveRow(c: any) { const e = edit[c.id]!; if (c.kind === 'custom' && !e.customType.trim()) { toast.err('Indique le type personnalisé (par exemple Premium ou Accès terrasse).'); return } try { await api(`/api/manage/categories/${c.id}`, { method: 'PATCH', body: { price: e.price, quota: e.quota, saleStart: dt(e.saleStart), saleEnd: dt(e.saleEnd), customType: c.kind === 'custom' ? e.customType.trim() : null, templateId: e.templateId || null } }); delete edit[c.id]; toast.ok('Catégorie mise à jour'); emit('refresh') } catch (er) { toast.err(errMsg(er)) } }
async function del(c: any) { if (!confirm(`Supprimer « ${c.name} » ?`)) return; try { await api(`/api/manage/categories/${c.id}`, { method: 'DELETE' }); emit('refresh') } catch (e) { toast.err(errMsg(e)) } }
</script>
<template>
  <div class="space-y-6">
    <p v-if="templatesError" class="text-sm text-red-300" role="alert">Impossible de charger les modèles de billets : {{ errMsg(templatesError) }}</p>
    <form class="card grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-6" @submit.prevent="add"><label class="block lg:col-span-2"><span class="label">Nom de la catégorie</span><input v-model="n.name" required placeholder="ex. Accès terrasse" class="input"></label><label class="block"><span class="label">Type de billet</span><select v-model="n.kind" class="input"><option v-for="k in kinds" :key="k[0]" :value="k[0]">{{ k[1] }}</option></select></label><label v-if="n.kind === 'custom'" class="block"><span class="label">Type personnalisé</span><input v-model="n.customType" required maxlength="80" placeholder="ex. Premium" class="input"></label><label class="block"><span class="label">Prix ({{ ev.currency }})</span><input v-model.number="n.price" type="number" min="0" :disabled="n.kind === 'free'" class="input"></label><label class="block"><span class="label">Quota</span><input v-model.number="n.quota" type="number" min="1" required class="input"></label><label class="block"><span class="label">Max / personne</span><input v-model.number="n.maxPerOrder" type="number" min="1" max="50" class="input"></label><label class="block sm:col-span-2 lg:col-span-3"><span class="label">Modèle de billet pour cette catégorie</span><select v-model="n.templateId" class="input"><option value="">Même modèle que l’événement ({{ eventTemplateLabel }})</option><option v-for="template in templates ?? []" :key="template.id" :value="template.id">{{ template.name }}{{ template.published ? '' : ' (brouillon)' }}</option></select></label><button class="btn btn-primary sm:col-span-2 lg:col-span-6" :disabled="busy">Ajouter la catégorie</button></form>
    <UiEmpty v-if="!ev.categories.length" title="Aucune catégorie" text="Ajoute au moins une catégorie pour pouvoir publier l’événement." />
    <div v-else class="space-y-3 md:hidden"><article v-for="c in ev.categories" :key="c.id" class="card space-y-4 p-4"><div><h3 class="break-words font-bold">{{ c.name }} <span v-if="ticketTypeLabel(c.kind, c.name, c.customType) !== c.name" class="chip ml-1 !py-0.5">{{ ticketTypeLabel(c.kind, c.name, c.customType) }}</span></h3><p class="mt-1 text-sm text-muted">{{ c.price === 0 ? 'Gratuit' : money(c.price, ev.currency) }} · {{ c.sold }} vendus · {{ c.reserved }} réservés sur {{ c.quota }}</p></div><template v-if="edit[c.id]"><div class="grid grid-cols-2 gap-3"><label v-if="c.kind === 'custom'" class="col-span-2 text-sm text-muted">Type personnalisé<input v-model="edit[c.id]!.customType" required maxlength="80" class="input mt-1"></label><label class="text-sm text-muted">Prix<input v-model.number="edit[c.id]!.price" type="number" min="0" class="input mt-1"></label><label class="text-sm text-muted">Quota<input v-model.number="edit[c.id]!.quota" type="number" :min="c.sold + c.reserved" class="input mt-1"></label><label class="text-sm text-muted">Début des ventes<input v-model="edit[c.id]!.saleStart" type="datetime-local" class="input mt-1"></label><label class="text-sm text-muted">Fin des ventes<input v-model="edit[c.id]!.saleEnd" type="datetime-local" class="input mt-1"></label><label class="col-span-2 text-sm text-muted">Modèle de billet<select v-model="edit[c.id]!.templateId" class="input mt-1"><option value="">Même modèle que l’événement ({{ eventTemplateLabel }})</option><option v-for="template in templates ?? []" :key="template.id" :value="template.id">{{ template.name }}</option></select></label></div><button class="btn btn-primary w-full" @click="saveRow(c)">Enregistrer</button></template><template v-else><p class="text-sm text-muted">{{ c.saleStart || c.saleEnd ? `${c.saleStart ? fdate(c.saleStart, { dateStyle: 'short' }) : '…'} → ${c.saleEnd ? fdate(c.saleEnd, { dateStyle: 'short' }) : '…'}` : 'Ventes sans date limite' }}</p><p class="text-sm text-muted">Modèle : {{ templateName(c.templateId) }}</p><div class="flex gap-2"><button class="btn btn-ghost flex-1" @click="start(c)">Modifier</button><button class="btn btn-danger flex-1" @click="del(c)">Supprimer</button></div></template></article></div>
    <div v-if="ev.categories.length" class="card hidden overflow-x-auto md:block"><table class="w-full min-w-[900px]"><thead><tr><th class="th">Catégorie</th><th class="th">Prix</th><th class="th">Quota</th><th class="th">Vendus</th><th class="th">Réservés</th><th class="th">Fenêtre de vente</th><th class="th">Modèle</th><th class="th" /></tr></thead>
      <tbody class="divide-y divide-line"><tr v-for="c in ev.categories" :key="c.id"><td class="td font-semibold">{{ c.name }} <span v-if="ticketTypeLabel(c.kind, c.name, c.customType) !== c.name" class="chip ml-1 !py-0.5">{{ ticketTypeLabel(c.kind, c.name, c.customType) }}</span><input v-if="edit[c.id] && c.kind === 'custom'" v-model="edit[c.id]!.customType" required maxlength="80" class="input mt-2 !min-h-[38px] w-40" aria-label="Type personnalisé"></td>
        <template v-if="edit[c.id]"><td class="td"><input v-model.number="edit[c.id]!.price" type="number" min="0" class="input !min-h-[38px] w-28"></td><td class="td"><input v-model.number="edit[c.id]!.quota" type="number" :min="c.sold + c.reserved" class="input !min-h-[38px] w-24"></td><td class="td">{{ c.sold }}</td><td class="td">{{ c.reserved }}</td><td class="td"><div class="flex gap-1"><input v-model="edit[c.id]!.saleStart" type="datetime-local" class="input !min-h-[38px]" aria-label="Début"><input v-model="edit[c.id]!.saleEnd" type="datetime-local" class="input !min-h-[38px]" aria-label="Fin"></div></td><td class="td"><select v-model="edit[c.id]!.templateId" class="input !min-h-[38px] min-w-48"><option value="">Modèle par défaut de l’événement</option><option v-for="template in templates ?? []" :key="template.id" :value="template.id">{{ template.name }}</option></select></td><td class="td text-right"><button class="btn btn-primary !min-h-[38px] px-3" @click="saveRow(c)">Enregistrer</button></td></template>
        <template v-else><td class="td">{{ c.price === 0 ? 'Gratuit' : money(c.price, ev.currency) }}</td><td class="td">{{ c.quota }}</td><td class="td">{{ c.sold }}</td><td class="td">{{ c.reserved }}</td><td class="td text-muted">{{ c.saleStart || c.saleEnd ? `${c.saleStart ? fdate(c.saleStart, { dateStyle: 'short' }) : '…'} → ${c.saleEnd ? fdate(c.saleEnd, { dateStyle: 'short' }) : '…'}` : 'Toujours' }}</td><td class="td text-muted">{{ templateName(c.templateId) || 'Modèle événementiel' }}</td><td class="td text-right"><button class="btn btn-ghost !min-h-[38px] px-3" @click="start(c)">Modifier</button> <button class="btn btn-danger !min-h-[38px] px-3" @click="del(c)">Supprimer</button></td></template></tr></tbody></table></div>
  </div>
</template>
